// Run with Electron on a disposable sample generated by workbench-sample.mjs.
const {app, BrowserWindow, ipcMain} = require('electron');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const {performance} = require('node:perf_hooks');
const {pathToFileURL} = require('node:url');
const [sample, stepArg, output] = process.argv.slice(2);
const root = fs.realpathSync(sample);
const evidenceRoot = path.resolve(__dirname,'../.hermes');
const relative = path.relative(evidenceRoot,root);
if (!/^bench-[^/]+\/(2k|4k)$/.test(relative) || fs.existsSync(output)) {
  throw Error('Choose a dedicated .hermes/bench-*/2k or 4k sample and a new result file.');
}
const fixture = JSON.parse(fs.readFileSync(path.join(root,'.storyboard-flow/checkpoints/project.json'),'utf8'));
if (fixture.id !== 'studio-sample' || !Number.isInteger(Number(stepArg)) || Number(stepArg)<1 || Number(stepArg)>=fixture.shots.length)
  throw Error('Expected a generated sample and a navigation range inside its active boards.');
const steps = Number(stepArg);
const userData = fs.mkdtempSync(path.join(os.tmpdir(),'flow-profile-'));
const entry = path.resolve(__dirname,'../dist-electron/platform/main/flowEditorEntry.js');
process.argv = [process.execPath,entry,root,userData,'--workbench'];
const started = performance.now();
const delay = ms => new Promise(resolve => setTimeout(resolve,ms));
const report = {cpu:os.cpus()[0].model,ramGiB:os.totalmem()/2**30,steps,samples:[]};
async function waitFor(check, label) {
  const deadline = performance.now()+30000;
  do { if(await check()) return; await delay(8); } while(performance.now()<deadline);
  throw Error('Timeout: '+label);
}
// Observe the existing handler without changing its arguments, result or timing policy.
const checkpointMs = [];
const handle = ipcMain.handle.bind(ipcMain);
ipcMain.handle = (channel, listener) => {
  if (channel !== 'flow-editor:checkpoint') return handle(channel, listener);
  return handle(channel, async (...args) => {
    const start = performance.now();
    try { return await listener(...args); }
    finally { checkpointMs.push(Math.round(performance.now()-start)); }
  });
};
async function profile() {
  await import(pathToFileURL(entry).href);
  await app.whenReady();
  let win;
  await waitFor(()=>win=BrowserWindow.getAllWindows()[0], 'window');
  const js = code => win.webContents.executeJavaScript(code);
  const ready = id => js(`(()=>{const viewer=document.querySelector('[data-current-shot="shot-${id}"]');
    const images=Array.from(viewer?.querySelectorAll('.image-stage > img')||[]);
    return images.length===3 && images.every(im=>im.complete && im.naturalWidth>0);})()`);
  await waitFor(()=>ready(0),'initial canvas');
  await waitFor(()=>js("document.querySelector('.wb-status')?.innerText.includes('Flow 内已保存')"),'initial checkpoint');
  report.openMs = Math.round(performance.now()-started);
  async function sampleMemory(position) {
    const processes = app.getAppMetrics();
    const mib = list => Math.round(list.reduce((sum,p)=>sum+p.memory.workingSetSize,0)/1024);
    report.samples.push({position,rendererMiB:mib(processes.filter(p=>p.type==='Tab')),processSumMiB:mib(processes)});
  }
  await sampleMemory(0);
  const times=[];
  for(let i=1;i<=steps;i++) {
    const begin=performance.now();
    await js('document.body.dispatchEvent(new KeyboardEvent("keydown",{key:"ArrowRight",bubbles:true}))');
    await waitFor(()=>ready(i),'decoded board '+i);
    times.push(performance.now()-begin);
    if(i===20 || i%100===0 || i===steps) {
      await sampleMemory(i);
      console.log('Decoded board',i,report.samples.at(-1));
    }
  }
  times.sort((a,b)=>a-b);
  report.flipMs={median:Math.round(times[Math.floor(times.length*.5)]),p95:Math.round(times[Math.floor(times.length*.95)]),max:Math.round(times.at(-1))};
  const point = await js(`(()=>{const r=document.querySelector('.wb-viewer .image-stage').getBoundingClientRect();
    return {x:Math.round(r.left+.4*r.width),y:Math.round(r.top+.4*r.height)}})()`);
  const revision=await js('document.querySelector("[data-workbench]").dataset.revision');
  function mouse(type,x){win.webContents.sendInputEvent({type,x,y:point.y,button:'left',clickCount:1});}
  mouse('mouseMove',point.x);
  const begin=performance.now();
  mouse('mouseDown',point.x);
  mouse('mouseMove',point.x+16);
  await waitFor(()=>js(`(()=>{const mirror=document.querySelector('.wb-grid [data-live-mirror]');if(!mirror)return false;
    const c=document.createElement('canvas');c.width=160;c.height=90;const ctx=c.getContext('2d');
    ctx.drawImage(mirror,0,0,160,90);const pixels=ctx.getImageData(0,0,160,90).data;
    for(let i=0;i<pixels.length;i+=4)if(pixels[i]>145&&pixels[i+1]<115&&pixels[i+2]<150)return true;return false})()`),'mirrored ink');
  report.firstVisibleStrokeMs=Math.round(performance.now()-begin);
  mouse('mouseUp',point.x+16);
  const released=performance.now();
  await waitFor(()=>js(`document.querySelector('[data-workbench]').dataset.revision!==${JSON.stringify(revision)} && document.querySelector('.wb-status').innerText.includes('Flow 内已保存')`),'stroke checkpoint');
  report.strokeCheckpointMs=Math.round(performance.now()-released);
  await sampleMemory('painted');
  if (process.env.FLOW_PROFILE_SCROLL === '1') {
    const scroll = await js(`(async()=>{
      const grid = document.querySelector('.wb-grid').closest('.wb-panel-body');
      const limit = grid.scrollHeight - grid.clientHeight, samples = [];
      if (limit <= 0) throw Error('Expected a scrollable grid');
      const frame = () => new Promise(resolve => requestAnimationFrame(resolve));
      for (let i=0; i<=120; i++) {
        const start=performance.now();
        grid.scrollTop = limit * (i<=60 ? i : 120-i) / 60;
        await frame(); await frame();
        samples.push(performance.now()-start);
      }
      return {distance:limit, steps:samples.length, p95TwoFramesMs:Math.round(samples.sort((a,b)=>a-b)[114])};
    })()`);
    report.scroll=scroll;
    await sampleMemory('scroll-return');
    await delay(10000);
    await sampleMemory('idle-10s');
  }
  report.mainCheckpointMs = checkpointMs;
  fs.writeFileSync(output,JSON.stringify(report,null,2));
  win.close();
}
profile().catch(error=>{report.error=String(error);fs.writeFileSync(output,JSON.stringify(report,null,2));app.exit(1);});
